// src/App.js
import React from 'react';
import { BrowserRouter as Router, Routes, Route } from 'react-router-dom';
import Navbar from './components/Navbar.jsx';
import Footer from './components/Footer.jsx';
import Modal from './components/Modal.jsx';
import HomePage from './pages/Home.jsx'
import OpportunitiesPage from './pages/Opportunities.jsx';
import AuthPage from './pages/Auth.jsx';
import ProfilePage from './pages/Profile.jsx';
import MyApplicationsPage from './pages/MyApplications.jsx';
import OpportunityDetailPage from './pages/OpportunityDetail.jsx';


// يمكنك إضافة صفحات أخرى هنا مثل OpportunityDetailsPage, ProfilePage, إلخ.

function App() {
  return (
    <Router>
      <div className="flex flex-col min-h-screen">
        <Navbar />
        <main className="flex-grow"> {/* هذا سيجعل المحتوى يملأ المساحة المتاحة */}
          <Routes>
            <Route path="/" element={<HomePage />} />
            <Route path="/opportunities" element={<OpportunitiesPage />} />
            
            
            {/* <Route path="/opportunities/:id" element={<OpportunityDetailsPage />} /> */}
            <Route path="/profile" element={<ProfilePage /> }/>
            {/* يمكنك إضافة مسارات أخرى هنا */}
           
            <Route path ="/myapplication" element={<MyApplicationsPage/>}/>
            <Route path ="/opportunity/:id" element={<OpportunityDetailPage/>}/>
             <Route path="/auth" element={<AuthPage />} />
          </Routes>
          
        </main>
        <Footer />
      </div>
    </Router>
  );
}

export default App;
